def load_research2_plan():
    import importlib.util
    path = ROOT / "scripts" / "research2_plan.py"
    spec = importlib.util.spec_from_file_location("research2_plan_cli_t", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def deterministic_selection(plan):
    """A CLI-valid selection built only from the frozen calibration data.

    No formal / boundary / holdout record is consulted; every parameter set is
    a real calibration candidate (or the policy-0 fixed-gap control re-targeted
    to its own formal target), so no dummy sample can slip past the CLI.
    """
    configs = {}
    for tag in plan.FORMAL_METHOD_TAGS:
        configs[tag] = {}
        for target in plan.METHOD_TARGETS:
            if tag == plan.METHOD_TAG_FIXEDGAP:
                entry = plan._unlimited_config(plan.target_bytes_for(target))
                entry["gap_cycles"] = 1000
                entry["candidate_id"] = "cal-fixedgap-g1000"
            else:
                mode = int(tag[1:])
                entry = dict(plan.calibration_candidates(mode)[0],
                             target_bytes=plan.target_bytes_for(target))
                entry["gap_cycles"] = 0
                entry["candidate_id"] = "cal-m%d-t%d-c0" % (mode, target)
            entry["matched"] = True
            configs[tag][str(target)] = entry
    return {"schema": plan.SELECTION_SCHEMA, "version": plan.SELECTION_VERSION,
            "targets": list(plan.METHOD_TARGETS),
            "window_cycles": plan.METHOD_WINDOW_CYCLES, "configs": configs}
